[CmdletBinding()]
param([string[]]$Categories = @('core','coding','research','knowledge','composite'), [string]$CodexHome = $(if ($env:CODEX_HOME) {$env:CODEX_HOME} else {Join-Path $HOME '.codex'}), [switch]$DryRun, [switch]$Repair)
$ErrorActionPreference = 'Stop'; $root = Split-Path -Parent $PSScriptRoot; $target = Join-Path $CodexHome 'skills'; $allowed = @('core','coding','research','knowledge','composite')
if ($Categories.Count -eq 1 -and $Categories[0] -match ',') { $Categories = $Categories[0].Split(',') | ForEach-Object { $_.Trim() } }
foreach ($category in $Categories) { if ($allowed -notcontains $category) { throw "Unknown category: $category" }; Get-ChildItem (Join-Path $root "skills/$category") -Directory | ForEach-Object { $source=$_.FullName; $dest=Join-Path $target $_.Name; if ($DryRun) { Write-Output "Would install $($_.Name) -> $source"; return }; New-Item -ItemType Directory -Force -Path $target | Out-Null; if (Test-Path -LiteralPath $dest) { $i=Get-Item -LiteralPath $dest -Force; if (-not ($i.Attributes -band [IO.FileAttributes]::ReparsePoint) -and -not $Repair) { throw "Destination exists and is not a link: $dest (use -Repair only after reviewing it)" }; if ($i.Attributes -band [IO.FileAttributes]::ReparsePoint) { [IO.Directory]::Delete($dest, $false) } else { Remove-Item -LiteralPath $dest -Recurse -Force } }; try { New-Item -ItemType SymbolicLink -Path $dest -Target $source -ErrorAction Stop | Out-Null } catch { New-Item -ItemType Junction -Path $dest -Target $source | Out-Null } } }
if (-not $DryRun) { Write-Output "Installed categories: $($Categories -join ', ')"; Write-Output "Codex skills path: $target" }
